      if (lookahead == 'i') ADVANCE(141);
      if (lookahead == '{') ADVANCE(87);
      if (lookahead == '|') ADVANCE(39);
      if (lookahead == '}') ADVANCE(90);
      if (lookahead == '~') ADVANCE(121);
